const envelope = $input.first().json;
const body = envelope.body ?? envelope;
const lead = body.lead ?? {};
const errors = [];
const interests = new Set(['Inteligencia Artificial','Automatización','Software Empresarial','Cloud','LCH Evidence AI','Otro']);
const freeDomains = new Set(['gmail.com','googlemail.com','hotmail.com','outlook.com','live.com','yahoo.com','icloud.com','me.com','proton.me','protonmail.com']);
const seniorTerms = ['ceo','cto','cio','coo','cdo','chief','director','directora','vp','vice president','gerente','head','presidente','president','owner','fundador','founder'];
const strategicInterests = new Set(['Inteligencia Artificial','Automatización','Software Empresarial','LCH Evidence AI']);
const isText = (value, min, max) => typeof value === 'string' && value.trim().length >= min && value.trim().length <= max;
if (body.schemaVersion !== 'lch.lead.v1') errors.push('schemaVersion');
if (!isText(body.leadId, 1, 128)) errors.push('leadId');
if (body.source !== 'website') errors.push('source');
if (body.status !== 'new') errors.push('status');
if (!isText(lead.nombre, 1, 80)) errors.push('nombre');
if (!isText(lead.apellido, 1, 80)) errors.push('apellido');
if (!isText(lead.email, 3, 254) || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(lead.email)) errors.push('email');
if (!isText(lead.empresa, 1, 160)) errors.push('empresa');
if (!isText(lead.cargo, 1, 160)) errors.push('cargo');
if (!interests.has(lead.interes)) errors.push('interes');
if (typeof lead.mensaje !== 'string' || lead.mensaje.length > 2000) errors.push('mensaje');
if (lead.consentimiento !== true) errors.push('consentimiento');
if (errors.length) return [{ json: { ok: false, route: 'INVALID', leadId: body.leadId ?? null, errors } }];
const normalized = {
  nombre: lead.nombre.trim().replace(/\s+/g, ' '),
  apellido: lead.apellido.trim().replace(/\s+/g, ' '),
  email: lead.email.trim().toLowerCase(),
  empresa: lead.empresa.trim().replace(/\s+/g, ' '),
  cargo: lead.cargo.trim().replace(/\s+/g, ' '),
  interes: lead.interes,
  mensaje: lead.mensaje.trim(),
  consentimiento: true,
};
let score = 0;
const reasons = [];
const domain = normalized.email.split('@')[1] ?? '';
const role = normalized.cargo.toLowerCase();
if (domain && !freeDomains.has(domain)) { score += 2; reasons.push('corporate_email'); }
if (seniorTerms.some((term) => role.includes(term))) { score += 3; reasons.push('decision_maker_role'); }
if (strategicInterests.has(normalized.interes)) { score += 2; reasons.push('strategic_interest'); }
if (normalized.mensaje.length >= 20) { score += 2; reasons.push('described_operational_challenge'); }
if (normalized.empresa.length >= 3) { score += 1; reasons.push('company_identified'); }
const priority = score >= 7 ? 'HOT' : score >= 4 ? 'WARM' : 'LOW';
return [{ json: { ok: true, route: priority, leadId: body.leadId, priority, score, reasons, lead: normalized, source: 'website', clientSubmittedAt: typeof body.submittedAt === 'string' ? body.submittedAt : null, receivedAt: new Date().toISOString() } }];
